var payments = gobreaker.NewCircuitBreaker[Receipt](gobreaker.Settings{
    Name:    "payments",
    Timeout: 15 * time.Second,                 // cooldown in the open state
    MaxRequests: 3,                            // half-open trial calls
    ReadyToTrip: func(c gobreaker.Counts) bool {
        return c.Requests >= 20 && float64(c.TotalFailures)/float64(c.Requests) > 0.5
    },
    IsExcluded: func(err error) bool { return errors.Is(err, context.Canceled) },
})

receipt, err := payments.Execute(func() (Receipt, error) {
    return api.Authorize(ctx, order)            // context timeout still needed
})

