type Breaker struct { // one per dependency; time.Now() has a monotonic reading in Go
    state atomic.Int32                   // 0 closed, 1 open, 2 half-open
    fails, total, tripped atomic.Int64   // tripped = UnixNano of the open transition
}
func (b *Breaker) Admit() bool {
    if b.state.Load() != Open {
        return true                                  // closed: admit and count
    }
    cooling := time.Since(time.Unix(0, b.tripped.Load())) < cooldown
    return !cooling && b.state.CompareAndSwap(Open, HalfOpen)  // else one trial call
}
